# owner: platform
import unittest
from hourglass.timesheet import timesheet_lines
from hourglass.models import Shift, Span


def _shift(worker, start, end):
    return Shift(worker, "mon", Span(start, end))


class TimesheetTests(unittest.TestCase):
    def test_busiest_first_with_hours(self):
        shifts = [
            _shift("Odell", 540, 930),
            _shift("Brisa", 540, 1020),
            _shift("Brisa", 540, 780),
            _shift("Quill", 600, 620)
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "Brisa: 2 shifts, 12.0 hours",
                "Odell: 1 shift, 6.5 hours",
                "Quill: 1 shift, 0.3 hours"
            ]
        )

    def test_equal_hours_sorted_by_name(self):
        shifts = [
            _shift("Zed", 540, 600),
            _shift("Amy", 540, 600)
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "Amy: 1 shift, 1.0 hours",
                "Zed: 1 shift, 1.0 hours"
            ]
        )

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker_raises(self):
        with self.assertRaises(ValueError):
            timesheet_lines([_shift("  ", 540, 600)])
